import re

_RANGE_RE = re.compile(r"^(-?\d+)\s*-\s*(-?\d+)$")


def _parse_part(part: str) -> list[int]:
    """把单个片段（"5" 或 "1-3"）展开成整数列表。"""
    match = _RANGE_RE.match(part)
    if match:
        start, end = int(match.group(1)), int(match.group(2))
        if start > end:
            raise ValueError(f"range start > end: {part!r}")
        return list(range(start, end + 1))
    if re.fullmatch(r"-?\d+", part):
        return [int(part)]
    raise ValueError(f"invalid range item: {part!r}")


def parse_range(spec: str) -> list[int]:
    """解析形如 "1,3-5,8" 的区间描述，返回展开后的整数列表。

    逗号分隔，每项可以是单个数字或闭区间 a-b；空字符串返回空列表。
    """
    if not spec or not spec.strip():
        return []
    result: list[int] = []
    for raw in spec.split(","):
        part = raw.strip()
        if not part:
            continue
        result.extend(_parse_part(part))
    return result

